class Solution { public:vector<int> leftmostBuildingQueries(vector<int>& heights,vector<vector<int>>& queries){vector<vector<pair<int,int>>> waiting(heights.size());vector<int> answer(queries.size(),-1);for(int index=0;index<(int)queries.size();++index){int left=min(queries[index][0],queries[index][1]),right=max(queries[index][0],queries[index][1]);if(left==right||heights[left]<heights[right])answer[index]=right;else waiting[right].push_back({heights[left],index});}priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pending;for(int building=0;building<(int)heights.size();++building){while(!pending.empty()&&pending.top().first<heights[building]){int index=pending.top().second;pending.pop();answer[index]=building;}for(auto query:waiting[building])pending.push(query);}return answer;} };
